);
await setupBrowserRuntime({ globals: globalThis });

const browser = await agent.browsers.get("iab");
const tab = await browser.tabs.get("iab-tab:475df9ff-5daf-446e-9ae5-f681d2029297");

const jobs = [
  { school: "天津大学", home: null, phrase: null, href: "https://yzb.tju.edu.cn/xwzx/tkss_xw/202607/t20260702_324675.htm" },
  { school: "中国科学技术大学", home: "https://yz.ustc.edu.cn/", phrase: "2027年推免生接收办法" },
  { school: "北京大学", home: "https://admission.pku.edu.cn/", phrase: "2027年接收推荐免试研究生办法" },
  { school: "武汉大学", home: "https://gs.whu.edu.cn/", phrase: "推免" },
  { school: "上海交通大学", home: "https://yzb.sjtu.edu.cn/", phrase: "预推免" },
];

const out = [];
for (const j of jobs) {
  const rec = { school: j.school };
  try {
    let target = j.href || null;
    if (!target) {
      await tab.goto(j.home);
      await tab.playwright.waitForLoadState({ state: "domcontentloaded" });
      const a = tab.playwright.locator("a").filter({ hasText: j.phrase });
      const n = await a.count();
      rec.candidates = [];
      for (let i = 0; i < n && i < 6; i++) {
        const el = a.nth(i);
        rec.candidates.push({
          href: await el.getAttribute("href"),
          text: (await el.innerText()).replace(/\s+/g, " ").slice(0, 110),
        });
      }
      const pick = rec.candidates.find((c) => c.href && !c.href.startsWith("javascript") && !c.href.startsWith("#"));
      target = pick && pick.href;
    }
    if (!target) { rec.error = "NO_TARGET"; out.push(rec); continue; }
    const abs = new URL(target, j.home || "https://yzb.tju.edu.cn/").href;
    rec.resolved = abs;
    await tab.goto(abs);
    await tab.playwright.waitForLoadState({ state: "domcontentloaded" });
    rec.title = await tab.title();
    rec.text = ((await tab.playwright.locator("body").innerText()) || "").replace(/\s+/g, " ").slice(0, 1800);
  } catch (e) {
    rec.error = String((e && e.message) || e);
  }
  out.push(rec);
}
out;", "title": "抓取各校预推免通知正文"}

