  "武汉大学2027年接收推免生 预报名 截止时间",
];

const out = [];
for (const q of queries) {
  const rec = { q };
  try {
    await tab.goto("https://www.so.com/s?q=" + encodeURIComponent(q));
    await tab.playwright.waitForLoadState({ state: "domcontentloaded" });
    await tab.playwright.waitForTimeout(800);
    const t = await tab.title();
    if (t && t.includes("验证")) { rec.captcha = true; out.push(rec); break; }
    const links = await tab.playwright.locator("a").all();
    const seen = new Set();
    const items = [];
    for (const l of links) {
      if (items.length >= 8) break;
      const h = await l.getAttribute("href");
      if (!h || !/^https?:\/\//.test(h)) continue;
      if (/so\.com|360\.cn|qihoo/.test(h)) continue;
      if (seen.has(h)) continue;
      seen.add(h);
      const tx = ((await l.innerText()) || "").replace(/\s+/g, " ").trim();
      if (tx.length < 8) continue;
      items.push({ t: tx.slice(0, 90), h });
    }
    rec.items = items;
    rec.text = ((await tab.playwright.locator("body").innerText()) || "").replace(/\s+/g, " ").slice(0, 1200);
  } catch (e) {
    rec.error = String((e && e.message) || e);
  }
  out.push(rec);
}
out;", "title": "检索预推免汇总与缺口校"}

