{"code": "const browserPluginRoot =
  process.env.ZCODE_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
const { join } = await import("node:path");
const { pathToFileURL } = await import("node:url");
const { setupBrowserRuntime } = await import(
  pathToFileURL(join(browserPluginRoot, "scripts", "browser-client.mjs")).href
);
await setupBrowserRuntime({ globals: globalThis });

const browser = await agent.browsers.get("iab");
const tab = await browser.tabs.get("iab-tab:475df9ff-5daf-446e-9ae5-f681d2029297");

const pages = [
  { n: "人大研招", u: "https://pgs.ruc.edu.cn/" },
  { n: "民大研究生院", u: "https://grs.muc.edu.cn/" },
  { n: "北航研招-推免", u: "https://yzb.buaa.edu.cn/info/1036/3610.htm" },
];

const out = [];
for (const p of pages) {
  const rec = { n: p.n };
  try {
    await tab.goto(p.u);
    await tab.playwright.waitForLoadState({ state: "domcontentloaded" });
    await tab.playwright.waitForTimeout(1500);
    rec.title = await tab.title();
    const t = ((await tab.playwright.locator("body").innerText()) || "").replace(/\s+/g, " ");
    rec.text = t.slice(0, 1300);
  } catch (e) { rec.error = String((e && e.message) || e).slice(0, 110); }
  out.push(rec);
}
out;", "title": "补查人大民大北航推免状态"}

